	//   "code": "BTC-ETH",
	//   "timestamp": 1584486737444,
	//   "total_ask_size": 16.76384456,
	//   "total_bid_size": 168.9020623,
	//   "orderbook_units":
	//    [ { ask_price: 0.02295077,
	//        "bid_price": 0.02161249,
	//        "ask_size": 3.57100696,
	//        "bid_size": 22.5303265 },
	//      { ask_price: 0.02295078,
	//        "bid_price": 0.02152658,
	//        "ask_size": 0.52451651,
	//        "bid_size": 2.30355128 },
	//      { ask_price: 0.02295086,
	//        "bid_price": 0.02150802,
	//        "ask_size": 1.585,
	//        "bid_size": 5 }, ... ],
	//   "stream_type": "SNAPSHOT" }
	var marketId *string = this.SafeString(message, "code")
	var symbol *string = this.SafeSymbol(marketId, nil, "-")
	var typeVar *string = this.SafeString(message, "stream_type")
	var options map[string]any = ccxt.SafeMapTyped(this.Options, "watchOrderBook")
	var limit *int64 = this.SafeInteger(options, "limit", 15)
	if (typeVar != nil && *typeVar == "SNAPSHOT") && !(ccxt.InOp(this.Orderbooks, symbol)) {
		if symbol != nil {
			this.Orderbooks[*symbol] = this.OrderBook(map[string]any{}, limit)
		}
	}
	var orderbook any
	if symbol != nil {
		orderbook = this.Orderbooks[*symbol]
	}
	// upbit always returns a snapshot of 15 topmost entries
	// the "REALTIME" deltas are not incremental
	// therefore we reset the orderbook on each update
	// and reinitialize it again with new bidasks
	var data []any = ccxt.SafeListTyped(message, "orderbook_units")
